  text_dark: "1E293B",
  text_mid:  "475569",
  text_light:"94A3B8",
  chip_bg:   "E0F2FE",   // light blue chip
  chip_text: "065A82",
  gold:      "F59E0B",   // amber highlight
  row_alt:   "E8F4FD",
};

const FONT_HEAD = "Trebuchet MS";
const FONT_BODY = "Calibri";

// ─── HELPERS ─────────────────────────────────────────────────────────────────
function topBar(slide, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color: color || C.accent },
    line: { color: color || C.accent, width: 0 },
  });
}

function slideTitle(slide, txt, light = false) {
  slide.addText(txt, {
    x: 0.45, y: 0.18, w: 9.1, h: 0.65,
    fontSize: 22, bold: true, fontFace: FONT_HEAD,
    color: light ? C.white : C.text_dark,
    margin: 0,
  });
}

function footer(slide, light = false) {
  slide.addText("SmolVLM  |  Hugging Face & Stanford  |  arxiv.org/abs/2504.05299", {
    x: 0.45, y: 5.42, w: 9.1, h: 0.18,
    fontSize: 8, fontFace: FONT_BODY,
    color: light ? "5599BB" : C.text_light,
    margin: 0,
  });
}

function kpiBox(slide, x, y, w, h, big, label, accent) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.white },
    shadow: { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.08 },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: w, h: 0.06,
    fill: { color: accent || C.accent },
    line: { color: accent || C.accent, width: 0 },
  });
  slide.addText(big, {
    x, y: y + 0.18, w, h: 0.7,
    fontSize: 34, bold: true, fontFace: FONT_HEAD,
    color: accent || C.primary,
    align: "center", margin: 0,
  });
  slide.addText(label, {
    x, y: y + 0.82, w, h: 0.5,
    fontSize: 11, fontFace: FONT_BODY,
    color: C.text_mid, align: "center", margin: 0,
  });
}

// ─── SLIDE 1 — TITLE ─────────────────────────────────────────────────────────
(function slide1() {
  const sl = pres.addSlide();
  sl.background = { color: C.bg_dark };

  // full-bleed decorative teal bar on left
