"use strict";
const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "SmolVLM: Redefining Small and Efficient Multimodal Models";
pres.author = "Hugging Face & Stanford University";

// ─── PALETTE ─────────────────────────────────────────────────────────────────
// Ocean / Deep-tech palette
const C = {
  bg_dark:   "0B1120",   // near-black navy  (title / closing slides)
  bg_light:  "F0F4F8",   // off-white        (content slides)
  primary:   "065A82",   // deep blue
  accent:    "0D9488",   // teal
  accent2:   "14B8A6",   // lighter teal
  white:     "FFFFFF",
  text_dark: "1E293B",
  text_mid:  "475569",
  text_light:"94A3B8",
  chip_bg:   "E0F2FE",   // light blue chip
  chip_text: "065A82",
  gold:      "F59E0B",   // amber highlight
  row_alt:   "E8F4FD",
};

const FONT_HEAD = "Trebuchet MS";
const FONT_BODY = "Calibri";

// ─── HELPERS ─────────────────────────────────────────────────────────────────
function topBar(slide, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color: color || C.accent },
    line: { color: color || C.accent, width: 0 },
  });
}

function slideTitle(slide, txt, light = false) {
  slide.addText(txt, {
    x: 0.45, y: 0.18, w: 9.1, h: 0.65,
    fontSize: 22, bold: true, fontFace: FONT_HEAD,
    color: light ? C.white : C.text_dark,
    margin: 0,
  });
}

function footer(slide, light = false) {
  slide.addText("SmolVLM  |  Hugging Face & Stanford  |  arxiv.org/abs/2504.05299", {
    x: 0.45, y: 5.42, w: 9.1, h: 0.18,
    fontSize: 8, fontFace: FONT_BODY,
    color: light ? "5599BB" : C.text_light,
    margin: 0,
  });
}

function kpiBox(slide, x, y, w, h, big, label, accent) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.white },
    shadow: { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.08 },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: w, h: 0.06,
    fill: { color: accent || C.accent },
    line: { color: accent || C.accent, width: 0 },
  });
  slide.addText(big, {
    x, y: y + 0.18, w, h: 0.7,
    fontSize: 34, bold: true, fontFace: FONT_HEAD,
    color: accent || C.primary,
    align: "center", margin: 0,
  });
  slide.addText(label, {
    x, y: y + 0.82, w, h: 0.5,
    fontSize: 11, fontFace: FONT_BODY,
    color: C.text_mid, align: "center", margin: 0,
  });
}

// ─── SLIDE 1 — TITLE ─────────────────────────────────────────────────────────
(function slide1() {
  const sl = pres.addSlide();
  sl.background = { color: C.bg_dark };

  // full-bleed decorative teal bar on left
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.25, h: 5.625,
    fill: { color: C.accent },
    line: { color: C.accent, width: 0 },
  });
  // subtle grid dots via rectangle shapes (decorative accent)
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 0.5, w: 2.8, h: 4.5,
    fill: { color: "0D2A45", transparency: 0 },
    line: { color: "0D2A45", width: 0 },
  });
  // teal accent corner
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 0.5, w: 0.05, h: 4.5,
    fill: { color: C.accent },
    line: { color: C.accent, width: 0 },
  });

  // Main title
  sl.addText("SmolVLM", {
    x: 0.55, y: 0.8, w: 6.2, h: 1.1,
    fontSize: 54, bold: true, fontFace: FONT_HEAD,
    color: C.white, margin: 0,
  });
  sl.addText("Redefining Small and Efficient\nMultimodal Models", {
    x: 0.55, y: 1.75, w: 6.2, h: 1.1,
    fontSize: 22, fontFace: FONT_HEAD,
    color: C.accent2, margin: 0,
  });

  // Tagline
  sl.addText("Sub-1 GB inference · 13-benchmark competitive · Fully open-source", {
    x: 0.55, y: 2.95, w: 6.2, h: 0.45,
    fontSize: 12, fontFace: FONT_BODY,
    color: "7FB8CF", italic: true, margin: 0,
  });

  // Author / org chips
  sl.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.55, y: 3.6, w: 1.8, h: 0.38,
    fill: { color: "0D9488", transparency: 60 },
    rectRadius: 0.06,
    line: { color: C.accent, width: 1 },
  });
  sl.addText("Hugging Face", {
    x: 0.55, y: 3.6, w: 1.8, h: 0.38,
    fontSize: 10, fontFace: FONT_BODY, color: C.accent2,
    align: "center", valign: "middle", margin: 0,
  });
  sl.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 2.5, y: 3.6, w: 1.8, h: 0.38,
    fill: { color: "0D9488", transparency: 60 },
    rectRadius: 0.06,
    line: { color: C.accent, width: 1 },
  });
  sl.addText("Stanford University", {
    x: 2.5, y: 3.6, w: 1.8, h: 0.38,
    fontSize: 10, fontFace: FONT_BODY, color: C.accent2,
    align: "center", valign: "middle", margin: 0,
  });

  // Key stat callout in right panel
  sl.addText("256M", {
    x: 7.05, y: 0.9, w: 2.7, h: 0.9,
    fontSize: 52, bold: true, fontFace: FONT_HEAD,
    color: C.accent2, align: "center", margin: 0,
  });
  sl.addText("parameters", {
    x: 7.05, y: 1.7, w: 2.7, h: 0.35,
    fontSize: 12, fontFace: FONT_BODY, color: "7FB8CF",
    align: "center", margin: 0,
  });
  sl.addShape(pres.shapes.LINE, {
    x: 7.3, y: 2.15, w: 2.2, h: 0,
    line: { color: C.accent, width: 0.8, transparency: 40 },
  });
  sl.addText("< 1 GB RAM", {
    x: 7.05, y: 2.3, w: 2.7, h: 0.45,
    fontSize: 18, bold: true, fontFace: FONT_HEAD,
    color: C.gold, align: "center", margin: 0,
  });
  sl.addText("on-device inference", {
    x: 7.05, y: 2.72, w: 2.7, h: 0.3,
    fontSize: 10, fontFace: FONT_BODY, color: "7FB8CF",
    align: "center", margin: 0,
  });
  sl.addShape(pres.shapes.LINE, {
    x: 7.3, y: 3.1, w: 2.2, h: 0,
    line: { color: C.accent, width: 0.8, transparency: 40 },
  });
  sl.addText("300×", {
    x: 7.05, y: 3.2, w: 2.7, h: 0.55,
    fontSize: 28, bold: true, fontFace: FONT_HEAD,
    color: C.gold, align: "center", margin: 0,
  });
  sl.addText("larger Idefics-80B\noutperformed", {
    x: 7.05, y: 3.7, w: 2.7, h: 0.5,
    fontSize: 10, fontFace: FONT_BODY, color: "7FB8CF",
    align: "center", margin: 0,
  });

  // arxiv citation
  sl.addText("arxiv.org/abs/2504.05299", {
    x: 0.55, y: 5.2, w: 5, h: 0.25,
    fontSize: 9, fontFace: FONT_BODY, color: "5599BB", margin: 0,
  });
})();

// ─── SLIDE 2 — PROBLEM / MOTIVATION ──────────────────────────────────────────
(function slide2() {
  const sl = pres.addSlide();
  sl.background = { color: C.bg_light };
  topBar(sl);
  slideTitle(sl, "Large VLMs Are Powerful but Impractical for Edge Deployment");
  footer(sl);

  // Left column — problem statement
  sl.addText("The Deployment Gap", {
    x: 0.45, y: 1.05, w: 4.5, h: 0.38,
    fontSize: 14, bold: true, fontFace: FONT_HEAD,
    color: C.primary, margin: 0,
  });

  const problems = [
    "State-of-the-art VLMs (GPT-4V, LLaVA-34B) require 20–80 GB GPU VRAM",
    "Mobile phones and edge devices typically have 4–16 GB total RAM",
    "Cloud inference adds latency, cost, and privacy concerns",
    "Prior compact VLMs traded accuracy for efficiency without principled design",
    "No principled framework for scaling-down multimodal architectures",
  ];
  sl.addText(problems.map((t, i) => ({
    text: t, options: { bullet: true, breakLine: i < problems.length - 1, color: C.text_dark, fontSize: 13, paraSpaceAfter: 5 }
  })), { x: 0.45, y: 1.5, w: 4.55, h: 3.2, fontFace: FONT_BODY, margin: 0 });

  // Right column — RAM comparison callout boxes
  const models = [
    { name: "GPT-4V / Large VLMs", ram: "~80 GB", color: "EF4444" },
    { name: "Molmo-A1B-7B (Efficient OS)", ram: "27.7 GB", color: "F97316" },
    { name: "SmolVLM-2.2B", ram: "4.9 GB", color: C.accent },
    { name: "SmolVLM-256M", ram: "0.8 GB", color: "059669" },
  ];
  sl.addText("GPU RAM Required at Inference", {
    x: 5.3, y: 1.05, w: 4.2, h: 0.35,
    fontSize: 12, bold: true, fontFace: FONT_HEAD,
    color: C.text_dark, margin: 0,
  });
  models.forEach((m, i) => {
    const y = 1.5 + i * 0.9;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y, w: 4.2, h: 0.75,
      fill: { color: C.white },
      shadow: { type: "outer", blur: 5, offset: 1, angle: 135, color: "000000", opacity: 0.07 },
    });
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y, w: 0.06, h: 0.75,
      fill: { color: m.color }, line: { color: m.color, width: 0 },
    });
    sl.addText(m.name, {
      x: 5.42, y: y + 0.08, w: 2.5, h: 0.3,
      fontSize: 11, fontFace: FONT_BODY, color: C.text_dark, margin: 0,
    });
    sl.addText(m.ram, {
      x: 7.9, y: y + 0.08, w: 1.5, h: 0.35,
      fontSize: 18, bold: true, fontFace: FONT_HEAD,
      color: m.color, align: "right", margin: 0,
    });
  });

  sl.addText("SmolVLM closes this gap through architectural innovation — not just scaling down.", {
    x: 0.45, y: 4.85, w: 9.1, h: 0.3,
    fontSize: 11, italic: true, fontFace: FONT_BODY,
    color: C.accent, margin: 0,
  });
})();

// ─── SLIDE 3 — ARCHITECTURE OVERVIEW ─────────────────────────────────────────
(function slide3() {
  const sl = pres.addSlide();
  sl.background = { color: C.bg_light };
  topBar(sl);
  slideTitle(sl, "SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone");
  footer(sl);

  // Architecture figure
  const fig3 = "/app/benchmark/assets/figure_3.jpg";
  if (fs.existsSync(fig3)) {
    sl.addImage({ path: fig3, x: 0.45, y: 0.95, w: 5.2, h: 3.5, sizing: { type: "contain", w: 5.2, h: 3.5 } });
  }

  // Pipeline steps on the right
