// ─── SLIDE 8 — ON-DEVICE DEPLOYMENT ──────────────────────────────────────────
(function slide8() {
  const sl = pres.addSlide();
  sl.background = { color: C.bg_light };
  topBar(sl, C.accent);
  slideTitle(sl, "Real-Time Inference on Apple Silicon: Up to 80 Tokens/Second");
  footer(sl);

  // Figure 2
  const fig2 = "/app/benchmark/assets/figure_2.jpg";
  if (fs.existsSync(fig2)) {
    sl.addImage({ path: fig2, x: 0.45, y: 1.0, w: 5.2, h: 3.4, sizing: { type: "contain", w: 5.2, h: 3.4 } });
