  sl.addText("HuggingSnap: On-Device Results", {
    x: 5.9, y: 1.0, w: 3.7, h: 0.38,
    fontSize: 13, bold: true, fontFace: FONT_HEAD, color: C.primary, margin: 0,
  });
  sl.addText("Processes photos & videos locally on iOS — no cloud dependency.", {
    x: 5.9, y: 1.4, w: 3.7, h: 0.32,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_mid, margin: 0,
  });

  const stats = [
    { device: "MacBook Pro M1 Max 64GB", tps: "~80 tok/s", model: "SmolVLM-256M, batch=1" },
