    { device: "High-end (batch=64)", tps: "~1000 tok/s", model: "SmolVLM-256M" },
  ];
  stats.forEach((s, i) => {
    const y = 1.85 + i * 0.95;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 5.9, y, w: 3.7, h: 0.82,
      fill: { color: C.white },
      shadow: { type: "outer", blur: 6, offset: 1, angle: 135, color: "000000", opacity: 0.08 },
    });
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 5.9, y, w: 0.06, h: 0.82,
      fill: { color: C.accent }, line: { color: C.accent, width: 0 },
    });
    sl.addText(s.tps, {
      x: 6.02, y: y + 0.05, w: 3.45, h: 0.38,
      fontSize: 20, bold: true, fontFace: FONT_HEAD, color: C.accent, margin: 0,
    });
    sl.addText(s.device, {
      x: 6.02, y: y + 0.42, w: 3.45, h: 0.22,
      fontSize: 9.5, fontFace: FONT_BODY, color: C.text_dark, margin: 0,
    });
    sl.addText(s.model, {
      x: 6.02, y: y + 0.6, w: 3.45, h: 0.18,
      fontSize: 8.5, fontFace: FONT_BODY, color: C.text_light, margin: 0,
    });
  });

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 5.9, y: 4.8, w: 3.7, h: 0.45,
    fill: { color: "E0F7F4" }, line: { color: C.accent, width: 1 },
  });
  sl.addText("Throughput scales ~linearly with batch size for the 256M model.", {
    x: 6.0, y: 4.8, w: 3.5, h: 0.45,
    fontSize: 10, fontFace: FONT_BODY, color: C.text_dark,
    valign: "middle", margin: 0,
  });
})();

